import{_ as d,o as r,c as e,a2 as a}from"./chunks/framework.CLq81i8L.js";const m=JSON.parse('{"title":"server 能力总览","description":"","frontmatter":{},"headers":[],"relativePath":"server/capabilities.md","filePath":"server/capabilities.md","lastUpdated":1785288787000}'),h={name:"server/capabilities.md"};function o(i,t,l,n,s,c){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="server-能力总览" tabindex="-1">server 能力总览 <a class="header-anchor" href="#server-能力总览" aria-label="Permalink to &quot;server 能力总览&quot;">​</a></h1><blockquote><p>最后更新: 2026-06-28</p></blockquote><h2 id="一、项目定位" tabindex="-1">一、项目定位 <a class="header-anchor" href="#一、项目定位" aria-label="Permalink to &quot;一、项目定位&quot;">​</a></h2><p><code>@server</code> 是 Schema Platform 的后端 API 服务，为可视化表单设计器、BPMN 流程引擎、AI 助手提供统一的数据层和业务逻辑层。</p><h2 id="二、技术栈" tabindex="-1">二、技术栈 <a class="header-anchor" href="#二、技术栈" aria-label="Permalink to &quot;二、技术栈&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层面</th><th>技术</th></tr></thead><tbody><tr><td>运行时</td><td>Node.js + TypeScript (ESM)</td></tr><tr><td>Web 框架</td><td>Koa.js</td></tr><tr><td>数据库</td><td>MongoDB 8 (Mongoose ODM)</td></tr><tr><td>认证</td><td>JWT + bcryptjs + OAuth2 授权码</td></tr><tr><td>AI 引擎</td><td>LangGraph (多 Agent 架构)</td></tr><tr><td>实时通信</td><td>Socket.IO</td></tr><tr><td>缓存</td><td>Redis (可选)</td></tr><tr><td>部署</td><td>传统 HTTP Server (自建服务器)</td></tr></tbody></table><h2 id="三、核心能力矩阵" tabindex="-1">三、核心能力矩阵 <a class="header-anchor" href="#三、核心能力矩阵" aria-label="Permalink to &quot;三、核心能力矩阵&quot;">​</a></h2><h3 id="_3-1-用户与权限体系" tabindex="-1">3.1 用户与权限体系 <a class="header-anchor" href="#_3-1-用户与权限体系" aria-label="Permalink to &quot;3.1 用户与权限体系&quot;">​</a></h3><table tabindex="0"><thead><tr><th>能力</th><th>说明</th><th>状态</th></tr></thead><tbody><tr><td>多租户隔离</td><td>AsyncLocalStorage + Mongoose 插件自动注入 tenantId</td><td>✅</td></tr><tr><td>RBAC 权限</td><td>角色-权限映射，中间件校验，Redis 缓存 (5min TTL)</td><td>✅</td></tr><tr><td>数据权限范围</td><td>all / dept / self / custom 四种模式</td><td>✅</td></tr><tr><td>SSO 单点登录</td><td>OAuth2 授权码模式，跨应用会话共享</td><td>✅</td></tr><tr><td>API Key 认证</td><td>机器对机器调用，支持权限范围和过期时间</td><td>✅</td></tr><tr><td>JWT + API Key 双通道</td><td>apiOrJwtAuth 中间件，灵活切换</td><td>✅</td></tr><tr><td>审计日志</td><td>自动记录写操作，含请求体、IP、用户</td><td>✅</td></tr><tr><td>登录日志</td><td>记录登录成功/失败，支持清空</td><td>✅</td></tr><tr><td>在线用户管理</td><td>基于 SSO 会话，支持强制下线</td><td>✅</td></tr><tr><td>密码策略</td><td>可配置的密码强度校验</td><td>✅</td></tr></tbody></table><h3 id="_3-2-组织架构" tabindex="-1">3.2 组织架构 <a class="header-anchor" href="#_3-2-组织架构" aria-label="Permalink to &quot;3.2 组织架构&quot;">​</a></h3><table tabindex="0"><thead><tr><th>能力</th><th>说明</th><th>状态</th></tr></thead><tbody><tr><td>部门管理</td><td>树形结构，支持移动（含循环检测）</td><td>✅</td></tr><tr><td>岗位管理</td><td>岗位 CRUD，支持排序和状态</td><td>✅</td></tr><tr><td>菜单管理</td><td>树形菜单，支持前端动态路由生成</td><td>✅</td></tr><tr><td>用户管理</td><td>CRUD + 批量导入导出 Excel</td><td>✅</td></tr><tr><td>租户管理</td><td>创建时自动初始化角色/管理员/菜单</td><td>✅</td></tr></tbody></table><h3 id="_3-3-schema-管理" tabindex="-1">3.3 Schema 管理 <a class="header-anchor" href="#_3-3-schema-管理" aria-label="Permalink to &quot;3.3 Schema 管理&quot;">​</a></h3><table tabindex="0"><thead><tr><th>能力</th><th>说明</th><th>状态</th></tr></thead><tbody><tr><td>Schema CRUD</td><td>创建、编辑、删除表单 Schema</td><td>✅</td></tr><tr><td>版本管理</td><td>自动推入版本快照（最多15个），支持查看/删除</td><td>✅</td></tr><tr><td>发布机制</td><td>草稿 → 发布，支持指定版本发布</td><td>✅</td></tr><tr><td>Schema 导入</td><td>深度校验 widget 树 + ID 重生成</td><td>✅</td></tr><tr><td>组件模板</td><td>模板 CRUD + 应用（返回重生成 ID 的 widgets）</td><td>✅</td></tr><tr><td>Mock 数据生成</td><td>根据 Schema 自动生成模拟表单数据</td><td>✅</td></tr></tbody></table><h3 id="_3-4-表单数据" tabindex="-1">3.4 表单数据 <a class="header-anchor" href="#_3-4-表单数据" aria-label="Permalink to &quot;3.4 表单数据&quot;">​</a></h3><table tabindex="0"><thead><tr><th>能力</th><th>说明</th><th>状态</th></tr></thead><tbody><tr><td>表单提交</td><td>按 Schema 提交数据</td><td>✅</td></tr><tr><td>提交管理</td><td>分页查询、状态筛选、单条/批量删除</td><td>✅</td></tr><tr><td>审批流程</td><td>submitted → approved / rejected 状态流转</td><td>✅</td></tr><tr><td>数据导出</td><td>CSV / Excel 格式导出</td><td>✅</td></tr><tr><td>批量操作</td><td>批量删除、批量更新状态</td><td>✅</td></tr></tbody></table><h3 id="_3-5-流程引擎" tabindex="-1">3.5 流程引擎 <a class="header-anchor" href="#_3-5-流程引擎" aria-label="Permalink to &quot;3.5 流程引擎&quot;">​</a></h3><table tabindex="0"><thead><tr><th>能力</th><th>说明</th><th>状态</th></tr></thead><tbody><tr><td>流程定义</td><td>CRUD + 发布 + 归档生命周期</td><td>✅</td></tr><tr><td>流程版本</td><td>版本化存储，支持多版本并存</td><td>✅</td></tr><tr><td>流程实例</td><td>启动、取消、状态查询、流程图获取</td><td>✅</td></tr><tr><td>任务管理</td><td>认领、完成、驳回、驳回到指定节点、委派</td><td>✅</td></tr><tr><td>批量审批</td><td>批量通过、批量驳回、批量委派</td><td>✅</td></tr><tr><td>审批日志</td><td>完整的审批轨迹记录</td><td>✅</td></tr><tr><td>流程通知</td><td>任务创建/超时/完成/委派/驳回/流程完成通知</td><td>✅</td></tr><tr><td>流程模板</td><td>内置模板 + 自定义模板，支持应用创建流程</td><td>✅</td></tr><tr><td>流程监控</td><td>概览、瓶颈分析、趋势分析</td><td>✅</td></tr><tr><td>中间事件</td><td>消息事件（发送/接收/完成）</td><td>✅</td></tr><tr><td>定时器</td><td>Timer Intermediate Event，Cron 触发</td><td>✅</td></tr><tr><td>数据导出</td><td>审批日志 CSV/Excel 导出</td><td>✅</td></tr></tbody></table><h3 id="_3-6-ai-能力" tabindex="-1">3.6 AI 能力 <a class="header-anchor" href="#_3-6-ai-能力" aria-label="Permalink to &quot;3.6 AI 能力&quot;">​</a></h3><table tabindex="0"><thead><tr><th>能力</th><th>说明</th><th>状态</th></tr></thead><tbody><tr><td>多 Agent 对话</td><td>LangGraph 驱动，Router → Editor/Flow/Page/General</td><td>✅</td></tr><tr><td>SSE 流式输出</td><td>thinking/text/tool_call/schema/flow/diff 事件</td><td>✅</td></tr><tr><td>HITL 中断-恢复</td><td>操作需确认时暂停，用户确认后继续</td><td>✅</td></tr><tr><td>RAG 语义搜索</td><td>BGE-M3 向量嵌入（SiliconFlow 托管）+ 余弦相似度检索 + 关键词降级</td><td>✅</td></tr><tr><td>多 LLM Provider</td><td>DeepSeek/OpenAI/Claude/Ollama，含路由策略</td><td>✅</td></tr><tr><td>LLM 配置优先级</td><td>用户请求配置 → 租户 DB 默认 → 平台 env → 报错引导</td><td>✅</td></tr><tr><td>PLATFORM_LLM_ENABLED</td><td>设为 false 可关闭平台托管 LLM，仅允许 DB 配置</td><td>✅</td></tr><tr><td>MCP 协议</td><td>SSE 传输的 Schema/Flow/Widget 三个 MCP Server</td><td>✅</td></tr><tr><td>版本管理</td><td>AI 生成内容自动版本化，支持 diff 和回滚</td><td>✅</td></tr><tr><td>插件市场</td><td>插件 CRUD + 安装/卸载</td><td>✅</td></tr><tr><td>提示词管理</td><td>模板 CRUD + 质量分析 + 反馈优化 + 测试</td><td>✅</td></tr><tr><td>行业 Agent</td><td>医疗/金融/教育行业专用模板</td><td>✅</td></tr><tr><td>行为学习</td><td>用户行为记录 → 偏好分析 → 个性化推荐</td><td>✅</td></tr><tr><td>Schema-Flow 同步</td><td>Schema 更新自动同步引用它的 Flow 节点</td><td>✅</td></tr><tr><td>@提及搜索</td><td>搜索 schema/flow/widget 并引用</td><td>✅</td></tr><tr><td>对话导出</td><td>导出为 JSON 格式</td><td>✅</td></tr><tr><td>AI 监控</td><td>Agent 性能统计、告警、概览</td><td>✅</td></tr><tr><td>消息反馈</td><td>正面/负面反馈，支持评论</td><td>✅</td></tr></tbody></table><h3 id="_3-7-集成与扩展" tabindex="-1">3.7 集成与扩展 <a class="header-anchor" href="#_3-7-集成与扩展" aria-label="Permalink to &quot;3.7 集成与扩展&quot;">​</a></h3><table tabindex="0"><thead><tr><th>能力</th><th>说明</th><th>状态</th></tr></thead><tbody><tr><td>Webhook</td><td>事件驱动，HMAC 签名验证，自动启动流程</td><td>✅</td></tr><tr><td>字典管理</td><td>字典类型 + 数据项，支持按编码查询</td><td>✅</td></tr><tr><td>系统参数</td><td>系统/业务参数，支持按 key 查询</td><td>✅</td></tr><tr><td>微前端应用</td><td>qiankun 微应用注册与管理</td><td>✅</td></tr><tr><td>文件上传</td><td>图片/头像/通用文件，静态文件访问</td><td>✅</td></tr><tr><td>仪表盘统计</td><td>Schema/Flow/AI/活动聚合统计</td><td>✅</td></tr><tr><td>事件总线</td><td>schema.published / submission.created / webhook.triggered</td><td>✅</td></tr></tbody></table><h3 id="_3-8-基础设施" tabindex="-1">3.8 基础设施 <a class="header-anchor" href="#_3-8-基础设施" aria-label="Permalink to &quot;3.8 基础设施&quot;">​</a></h3><table tabindex="0"><thead><tr><th>能力</th><th>说明</th><th>状态</th></tr></thead><tbody><tr><td>全局错误处理</td><td>errorHandler 中间件，统一错误响应</td><td>✅</td></tr><tr><td>请求超时</td><td>30秒超时，SSE 端点自动跳过</td><td>✅</td></tr><tr><td>请求校验</td><td>Zod Schema 校验中间件</td><td>✅</td></tr><tr><td>CORS</td><td>可配置的跨域来源</td><td>✅</td></tr><tr><td>Helmet</td><td>安全头</td><td>✅</td></tr><tr><td>优雅关闭</td><td>SIGTERM/SIGINT 信号处理</td><td>✅</td></tr><tr><td>优雅关闭</td><td>SIGTERM/SIGINT 信号处理</td><td>✅</td></tr><tr><td>Redis 缓存</td><td>可选的缓存层，支持 key 模式删除</td><td>✅</td></tr><tr><td>结构化日志</td><td>统一日志格式</td><td>✅</td></tr><tr><td>数据库种子</td><td>权限/角色/菜单/管理员/微应用/模板/OAuth 客户端</td><td>✅</td></tr><tr><td>数据库迁移</td><td>src/migrations/ 目录，角色迁移脚本</td><td>✅</td></tr></tbody></table><h2 id="四、已知-todo-未完成功能" tabindex="-1">四、已知 TODO / 未完成功能 <a class="header-anchor" href="#四、已知-todo-未完成功能" aria-label="Permalink to &quot;四、已知 TODO / 未完成功能&quot;">​</a></h2><table tabindex="0"><thead><tr><th>端点</th><th>当前状态</th><th>说明</th></tr></thead><tbody><tr><td><code>POST /api/ai/runtime/recommend-assignee</code></td><td>规则引擎占位</td><td>智能指派人推荐待接入 AI</td></tr><tr><td><code>POST /api/ai/runtime/evaluate-condition</code></td><td>返回固定 true</td><td>条件表达式评估待实现</td></tr><tr><td><code>POST /api/ai/runtime/predict-outcome</code></td><td>返回默认值</td><td>审批结果预测待实现</td></tr><tr><td><code>POST /api/ai/runtime/approval-suggestion</code></td><td>返回通用建议</td><td>审批建议待实现</td></tr><tr><td>在线用户/今日访问统计</td><td>返回 0</td><td>活跃度统计待实现</td></tr></tbody></table><h2 id="五、架构特点" tabindex="-1">五、架构特点 <a class="header-anchor" href="#五、架构特点" aria-label="Permalink to &quot;五、架构特点&quot;">​</a></h2><ol><li><strong>分层清晰</strong>: 路由 → 中间件 → 模型，职责分明</li><li><strong>多租户原生</strong>: 从中间件到模型层的全链路租户隔离</li><li><strong>事件驱动</strong>: EventBus 解耦 Schema 发布、表单提交、Webhook 触发</li><li><strong>AI-First</strong>: LangGraph 多 Agent 架构，支持流式输出和人机协作</li><li><strong>ObjectId 主键</strong>: 所有模型使用 MongoDB 原生 ObjectId，数据引用一致性好</li></ol>',27)])])}const u=d(h,[["render",o]]);export{m as __pageData,u as default};
